import "server-only";
import type { UIMessage } from "ai";
import { and, asc, desc, eq, lt, or, sql } from "drizzle-orm";
import type { BatchItem } from "drizzle-orm/batch";
import { z } from "zod";
import { db } from "@/db";
import { chatMessages, chats } from "@/db/schema";

/** Chat ids are generated by the client, so they're validated as opaque tokens. */
export const chatIdSchema = z.string().regex(/^[A-Za-z0-9_-]{8,64}$/, "Invalid chat id");

export const CHAT_PAGE_SIZE = 30;

export type ChatSummary = { id: string; title: string; updatedAt: number };
export type ChatPage = { items: ChatSummary[]; nextCursor: string | null };

/** The chat with its messages, or null when it doesn't exist or belongs to someone else. */
export async function loadChat(userId: string, chatId: string) {
  const [chat] = await db.select().from(chats).where(and(eq(chats.id, chatId), eq(chats.userId, userId))).limit(1);
  if (!chat) return null;
  const rows = await db.select().from(chatMessages).where(eq(chatMessages.chatId, chatId)).orderBy(asc(chatMessages.position));
  const messages = rows.map((row) => ({ id: row.id, role: row.role, parts: row.parts }) as UIMessage);
  return { chat, messages };
}

function titleFrom(message: UIMessage) {
  const text = message.parts.map((part) => (part.type === "text" ? part.text : "")).join(" ").replace(/\s+/g, " ").trim();
  return text.length > 80 ? `${text.slice(0, 79)}…` : text || "New chat";
}

/** Creates the chat on its first message. Throws FORBIDDEN when the id belongs to another user. */
export async function ensureChat(userId: string, chatId: string, firstMessage: UIMessage) {
  await db.insert(chats).values({ id: chatId, userId, title: titleFrom(firstMessage) }).onConflictDoNothing();
  const [chat] = await db.select({ userId: chats.userId }).from(chats).where(eq(chats.id, chatId)).limit(1);
  if (chat?.userId !== userId) throw new Error("FORBIDDEN");
}

/** Upserts messages by id; `offset` is the position of the first one in the chat. */
export async function saveMessages(chatId: string, messages: UIMessage[], offset = 0) {
  if (messages.length === 0) return;
  const touch: BatchItem<"sqlite"> = db.update(chats).set({ updatedAt: new Date() }).where(eq(chats.id, chatId));
  const upserts: BatchItem<"sqlite">[] = messages.map((message, index) =>
    db
      .insert(chatMessages)
      .values({ id: message.id, chatId, role: message.role, parts: message.parts, position: offset + index })
      .onConflictDoUpdate({ target: chatMessages.id, set: { parts: message.parts, position: offset + index } }),
  );
  await db.batch([touch, ...upserts]);
}

/** Newest first. The cursor is `<updatedAt>:<id>` of the last item on the previous page. */
export async function listChats(userId: string, { cursor, query }: { cursor?: string | null; query?: string | null }): Promise<ChatPage> {
  const conditions = [eq(chats.userId, userId)];
  if (query?.trim()) {
    const pattern = `%${query.trim().replace(/[\\%_]/g, "\\$&")}%`;
    conditions.push(sql`${chats.title} like ${pattern} escape '\\'`);
  }
  if (cursor) {
    const [time, id] = cursor.split(":");
    const updatedAt = new Date(Number(time));
    if (id && !Number.isNaN(updatedAt.getTime())) {
      conditions.push(or(lt(chats.updatedAt, updatedAt), and(eq(chats.updatedAt, updatedAt), lt(chats.id, id)))!);
    }
  }
  const rows = await db
    .select({ id: chats.id, title: chats.title, updatedAt: chats.updatedAt })
    .from(chats)
    .where(and(...conditions))
    .orderBy(desc(chats.updatedAt), desc(chats.id))
    .limit(CHAT_PAGE_SIZE + 1);
  const items = rows.slice(0, CHAT_PAGE_SIZE).map((row) => ({ id: row.id, title: row.title, updatedAt: row.updatedAt.getTime() }));
  const last = items.at(-1);
  return { items, nextCursor: rows.length > CHAT_PAGE_SIZE && last ? `${last.updatedAt}:${last.id}` : null };
}

export async function deleteChat(userId: string, chatId: string) {
  const [chat] = await db.select({ id: chats.id }).from(chats).where(and(eq(chats.id, chatId), eq(chats.userId, userId))).limit(1);
  if (!chat) throw new Error("NOT_FOUND");
  await db.batch([db.delete(chatMessages).where(eq(chatMessages.chatId, chatId)), db.delete(chats).where(eq(chats.id, chatId))]);
}
